from functools import wraps
from flask import jsonify
from flask_jwt_extended import verify_jwt_in_request, get_jwt_identity


def jwt_required(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        try:
            verify_jwt_in_request()
        except Exception as e:
            return jsonify({"error": "Unauthorized", "message": str(e)}), 401
        return f(*args, **kwargs)

    return wrapper


def admin_required(f):
    @wraps(f)
    @jwt_required
    def wrapper(*args, **kwargs):
        identity = get_jwt_identity()
        if identity.get("role") != "admin":
            return jsonify({"error": "Forbidden", "message": "Admin access required"}), 403
        return f(*args, **kwargs)

    return wrapper

from flask import current_app
from app.extensions import limiter


def init_limiter(app):
    limiter.init_app(app)


def rate_limit(limit_value=None):
    def decorator(f):
        limit = limit_value or current_app.config.get("RATELIMIT_DEFAULT", "100 per minute")
        return limiter.limit(limit)(f)

    return decorator

from flask import jsonify
from marshmallow import ValidationError
from werkzeug.exceptions import HTTPException, TooManyRequests


def register_error_handlers(app):
    @app.errorhandler(400)
    def bad_request(error):
        return jsonify({"error": "Bad Request", "message": str(error)}), 400

    @app.errorhandler(404)
    def not_found(error):
        return jsonify({"error": "Not Found", "message": str(error)}), 404

    @app.errorhandler(405)
    def method_not_allowed(error):
        return jsonify({"error": "Method Not Allowed", "message": str(error)}), 405

    @app.errorhandler(422)
    def unprocessable_entity(error):
        return jsonify({"error": "Unprocessable Entity", "message": str(error)}), 422

    @app.errorhandler(429)
    def rate_limit_exceeded(error):
        return jsonify({
            "error": "Too Many Requests",
            "message": "Rate limit exceeded. Please try again later.",
        }), 429

    @app.errorhandler(500)
    def internal_error(error):
        return jsonify({
            "error": "Internal Server Error",
            "message": "An unexpected error occurred.",
        }), 500

    @app.errorhandler(ValidationError)
    def validation_error(error):
        return jsonify({"error": "Validation Error", "messages": error.messages}), 422

    @app.errorhandler(HTTPException)
    def http_exception(error):
        return jsonify({
            "error": error.name,
            "message": error.description,
        }), error.code

    @app.errorhandler(Exception)
    def unhandled_exception(error):
        app.logger.exception("Unhandled exception: %s", str(error))
        return jsonify({
            "error": "Internal Server Error",
            "message": "An unexpected error occurred.",
        }), 500

from marshmallow import Schema, fields, validate, validates, ValidationError


class UserCreateSchema(Schema):
    username = fields.String(
        required=True,
        validate=[validate.Length(min=3, max=80), validate.Regexp(r"^[a-zA-Z0-9_]+$")],
    )
    email = fields.Email(required=True)
    password_hash = fields.String(
        required=True,
        validate=validate.Length(min=8, max=128),
        data_key="password",
    )


class UserUpdateSchema(Schema):
    username = fields.String(validate=[validate.Length(min=3, max=80), validate.Regexp(r"^[a-zA-Z0-9_]+$")])
    email = fields.Email()
    password_hash = fields.String(
        validate=validate.Length(min=8, max=128),
        data_key="password",
    )
    is_active = fields.Boolean()


class LoginSchema(Schema):
    username = fields.String(required=True)
    password = fields.String(required=True)


class PaginationSchema(Schema):
    page = fields.Integer(validate=validate.Range(min=1), load_default=1)
    per_page = fields.Integer(validate=validate.Range(min=1, max=100), load_default=20)

    @validates("per_page")
    def validate_per_page(self, value):
        if value > 100:
            raise ValidationError("per_page must not exceed 100")

from flask import request, url_for, current_app


def paginate_query(query, schema=None):
    page = request.args.get("page", type=int)
    per_page = request.args.get("per_page", type=int)

    if page is None:
        page = current_app.config.get("PAGINATION_DEFAULT_PAGE", 1)
    if per_page is None:
        per_page = current_app.config.get("PAGINATION_DEFAULT_PER_PAGE", 20)

    max_per_page = current_app.config.get("PAGINATION_MAX_PER_PAGE", 100)
    if per_page > max_per_page:
        per_page = max_per_page
    if page < 1:
        page = 1

    paginated = query.paginate(page=page, per_page=per_page, error_out=False)

    return {
        "data": [item.to_dict() for item in paginated.items],
        "pagination": {
            "page": paginated.page,
            "per_page": paginated.per_page,
            "total": paginated.total,
            "pages": paginated.pages,
            "has_next": paginated.has_next,
            "has_prev": paginated.has_prev,
        },
    }

